import json
d=json.load(open('candidate-import.json'))
def sk(o,ind=0,depth=0):
    if depth>4: return
    if isinstance(o,dict):
        for k,v in o.items():
            s = v if isinstance(v,(int,float,bool)) or v is None else (v[:100] if isinstance(v,str) else type(v).__name__+('[%d]'%len(v)))
            print(' '*ind+k+': '+str(s)); 
